using System.Collections.Generic;
using UnityEngine;

namespace Meowdieval.FoliageForge
{
    /// <summary>
    /// The baked variants of one tree type (<c>Oak_V1</c>, <c>Oak_V2</c>, ...) with a pick weight each.
    /// Generated by "Bake All Variants" in the Foliage Forge window; the foliage brush places a weighted random prefab of the set per tree.
    /// </summary>
    [CreateAssetMenu(fileName = "NewTreeVariantSet", menuName = "Meowdieval/Foliage Forge/Tree Variant Set")]
    public sealed class TreeVariantSet : ScriptableObject
    {
        [Tooltip("Tree type these variants belong to, from the recipe's Type Id.")]
        public string TypeId;
        public List<GameObject> Prefabs = new List<GameObject>();
        [Tooltip("Pick weight of each prefab, same order. 0 = never picked. Missing entries count as 1.")]
        public List<float> Weights = new List<float>();

        /// <summary>Pick weight of prefab <paramref name="index"/>; 1 when none is stored.</summary>
        public float Weight(int index) => index >= 0 && index < Weights.Count ? Weights[index] : 1f;

        /// <summary>A prefab picked with probability proportional to its weight; null when no prefab has a weight above 0.</summary>
        public GameObject Pick(System.Random rng)
        {
            double total = 0;
            for (int i = 0; i < Prefabs.Count; i++) if (Prefabs[i] != null && Weight(i) > 0f) total += Weight(i);
            if (total <= 0) return null;
            double r = rng.NextDouble() * total;
            GameObject last = null;
            for (int i = 0; i < Prefabs.Count; i++)
            {
                if (Prefabs[i] == null || Weight(i) <= 0f) continue;
                last = Prefabs[i];
                r -= Weight(i);
                if (r < 0) return last;
            }
            return last; // rounding
        }

        void OnValidate()
        {
            while (Weights.Count < Prefabs.Count) Weights.Add(1f);
            if (Weights.Count > Prefabs.Count) Weights.RemoveRange(Prefabs.Count, Weights.Count - Prefabs.Count);
        }
    }
}
